       const response = await fetch("/brands.json")
       if (!response.ok) {
         throw new Error(`HTTP error fetching brands: ${response.status}`)
       }
       const { brands } = (await response.json()) as { brands: string[] }
-      matcherRef.current = new BrandMatcher(brands)
+      if (!cancelled) {
+        matcherRef.current = new BrandMatcher(brands)
+      }
